entries[307740] = { ["name"] = "Tal der Reinheit", ["text"] = "Pakt-Fähigkeit\n60 Astrale Macht / 100 Energie / 60 Wut / 50% von Grundmana 20 Meter Reichweite\nSofort 20 sek. Abklingzeit\nWächter\nErfüllt den Zielbereich für 16 Sek. mit Anima. Innerhalb des Tals werden Eure Hauptwert und Ausdauer um 20% erhöht und Ihr erhaltet alle 4 Sek. 'Aufspießen'.\n\n'Aufspießen'\nSchließt die Abklingzeit von 'Zerfleischen' ab und lässt die Fähigkeit zusätzlich 4 Wut erzeugen.\n\nWildheit\nErfüllt den Zielbereich für 16 Sek. mit Anima. Innerhalb des Tals werden Eure Hauptwert und Ausdauer um 20% erhöht und Ihr erhaltet alle 4 Sek. 'Freizaubern'.\n\n'Freizaubern'\nEuer nächster Einsatz von 'Schreddern', 'Hauen' oder [ Brutales Schlitzen : 'Brutales Schlitzen' / 'Prankenhieb'] kostet keine Energie [ Moment der Klarsicht : und verursacht 0% mehr Schaden ].\n\nWiederherstellung\nErfüllt den Zielbereich für 16 Sek. mit Anima. Innerhalb des Tals werden Eure Hauptwert und Ausdauer um 20% erhöht und Ihr erhaltet alle 4 Sek. 'Freizaubern'.\n\n'Freizaubern'\nEuer nächster Einsatz von 'Nachwachsen' ist kostenlos.\n\nGleichgewicht\nErfüllt den Zielbereich für 16 Sek. mit Anima. Innerhalb des Tals werden Eure Hauptwert und Ausdauer um 20% erhöht und Ihr erhaltet alle 4 Sek. 'Solarermächtigung'.\n\n'Solarermächtigung'\nVerringert die Zauberzeit Eures nächsten Einsatzes von 'Solarzorn' um 4% und verursacht dabei eine Explosion, die allen Gegnern in der Nähe zusätzlich 4% des Schadens zufügt." }
entries[307741] = { ["name"] = "Befehligung des Hains", ["text"] = "Animabonus\nSofort\nDie Abklingzeit von 'Tal der Reinheit' wird auf 20 Sek. verringert, aber der Einsatz kostet [ Gleichgewicht : 60 Astrale Macht / Wildheit : 100 Energie / Wächter : 60 Wut /\n\nWiederherstellung\n10.000 Mana ]" }
