entries[308489] = { ["name"] = "Erfrischung", ["text"] = "Sofort\nStellt im Verlauf von 20 Sek. ( 22500 / 5 * 20) Gesundheit und ( 30000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 80 Tempo." }
entries[308490] = { ["name"] = "Schattenregen", ["text"] = "60 Meter Reichweite\nWirken in 1 sek. 3 sek. Abklingzeit\nFeuert ein Geschoss auf ein zufälliges Ziel ab. Wenn das Geschoss einschlägt, fügt es Gegnern innerhalb von 5 Metern um diesen Zielort 30 Schattenschaden zu." }
entries[308491] = { ["name"] = "Resonierender Pfeil", ["text"] = "Pakt-Fähigkeit\n40 Meter Reichweite\nSofort 1 min Abklingzeit\nVerschießt einen resonierenden Pfeil auf den Zielort, der Gegnern im Bereich (20% der Angriffskraft) Arkanschaden zufügt und den Bereich für 10 Sek. mit widerhallender Anima füllt. Der Effekt lässt Eure Angriffe die Sichtlinie zu Gegnern im Bereich ignorieren. Außerdem wird Eure kritische Trefferchance gegen sie um 30% erhöht.\n\nAuch nach Verlassen des Bereichs widerhallender Anima kann der Jäger noch 4 Sek. lang die Sichtlinie zum Gegner ignorieren." }
entries[308493] = { ["name"] = "Anvisiert", ["text"] = "Sofort\nDie Luftüberwachungseinheit erfasst fliegende Gegner in der Nähe und schießt sie ab." }
